# city names: one $FF-terminated string per table entry
NAME_TABLE = (0xA37B, 101)
# rail links: per city, (city, slot+time) pairs ending in 0
LINK_TABLE = (0xA2B1, 101)
# per-city byte tables (base, stride): one source line per city
